import torch

def core(q,k,v,do):
    dtype=q.dtype
    qh,kh,vh,dh=(t.to(torch.float16) for t in (q,k,v,do))
    f=torch.ops.aten._scaled_dot_product_flash_attention.default(qh,kh,vh,0.0,True,False)
    grads=torch.ops.aten._scaled_dot_product_flash_attention_backward.default(
        dh,qh,kh,vh,f[0],f[1],f[2],f[3],f[4],f[5],0.0,True,f[6],f[7])
    return torch.stack(grads).to(dtype)

compiled_core=torch.compile(core,fullgraph=True,mode="reduce-overhead")

def kernel(q,k,v,do):
    return compiled_core(q,k,v,do).clone()
